// Daily Operational Brief — Canonical Monetary & Temporal Brief Contract (frihet-mcp#257)
// Answers: '¿Qué debería revisar hoy en mi negocio y por qué?'
// Enforces all 5 canonical rules:
// 1. Absent != 0: {} -> amount: null, provenance: 'unavailable', unavailableCount: 1.
// 2. Multi-currency separation: 100 EUR + 100 USD -> amount: null, currency: 'MIXED',
//    provenance: 'mixed_currency_unconverted', totalsByCurrency: { EUR: ..., USD: ... }.
// 3. Canonical discounts & taxes: line discount, document discountRate, taxRate,
//    equivalenceSurchargeRate, irpfRate over discounted tax-exclusive base; fail closed
//    on pricesIncludeTax, deductLineDiscountAmounts, compoundTaxes, prepayment.
// 4. Honest unpaid nominal wording: realOutstandingBalanceDeterminable: false,
//    unpaidNominalSemantics: 'nominal_unpaid_invoice_totals_without_partial_payments',
//    and label 'Importe nominal de facturas no marcadas como pagadas (saldo pendiente real no determinable sin cobros parciales)'.
// 5. Explicit temporal scope: coverage.temporalScope = 'unfiltered_operational_sample_as_of_date'
//    plus currentMonthActivity separating the operational sample as of asOfDate from periodMonth.

const roundCurrency = (value) => Math.round(value * 100) / 100;

const computeCanonicalDocumentTotal = (doc) => {
  if (!doc || typeof doc !== 'object') return null;
  const rawItems = doc.items;
  if (!Array.isArray(rawItems) || rawItems.length === 0) return null;
  if (doc.pricesIncludeTax === true || doc.deductLineDiscountAmounts === true) return null;
  if (Array.isArray(doc.compoundTaxes) && doc.compoundTaxes.length > 0) return null;
  if (doc.prepayment !== undefined && doc.prepayment !== null && doc.prepayment !== 0) return null;

  const docDiscountPct = doc.discountRate === undefined || doc.discountRate === null ? 0 : doc.discountRate;
  const docTaxRate = doc.taxRate === undefined || doc.taxRate === null ? 0 : doc.taxRate;
  const docIrpfRate = doc.irpfRate === undefined || doc.irpfRate === null ? 0 : doc.irpfRate;
  const docSurchargeRate = doc.equivalenceSurchargeRate === undefined || doc.equivalenceSurchargeRate === null ? 0 : doc.equivalenceSurchargeRate;

  for (const rate of [docDiscountPct, docTaxRate, docIrpfRate, docSurchargeRate]) {
    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate < 0 || rate > 100) return null;
  }

  const baseByRate = new Map();
  let subtotalBeforeDiscount = 0;

  for (const item of rawItems) {
    if (!item || typeof item !== 'object') return null;
    if (typeof item.quantity !== 'number' || !Number.isFinite(item.quantity) || item.quantity < 0) return null;
    if (typeof item.unitPrice !== 'number' || !Number.isFinite(item.unitPrice) || item.unitPrice < 0) return null;
    if (item.discountAmount !== undefined && item.discountAmount !== null && item.discountAmount !== 0) return null;

    const lineDiscountPct = item.discount === undefined || item.discount === null ? 0 : item.discount;
    if (typeof lineDiscountPct !== 'number' || !Number.isFinite(lineDiscountPct) || lineDiscountPct < 0 || lineDiscountPct > 100) return null;

    const effectiveRate = item.taxRate === undefined || item.taxRate === null ? docTaxRate : item.taxRate;
    if (typeof effectiveRate !== 'number' || !Number.isFinite(effectiveRate) || effectiveRate < 0 || effectiveRate > 100) return null;

    const effectiveUnitPrice = roundCurrency(item.unitPrice * (1 - lineDiscountPct / 100));
    const lineBase = roundCurrency(item.quantity * effectiveUnitPrice);
    baseByRate.set(effectiveRate, roundCurrency((baseByRate.get(effectiveRate) || 0) + lineBase));
    subtotalBeforeDiscount = roundCurrency(subtotalBeforeDiscount + lineBase);
  }

  const documentDiscount = roundCurrency(subtotalBeforeDiscount * (docDiscountPct / 100));
  const subtotal = roundCurrency(subtotalBeforeDiscount - documentDiscount);

  const discountedBaseByRate = new Map();
  const sortedRates = Array.from(baseByRate.keys()).sort((a, b) => b - a);
  if (docDiscountPct > 0 && subtotalBeforeDiscount > 0) {
    const discountFactor = 1 - docDiscountPct / 100;
    let otherGroupsTotal = 0;
    sortedRates.forEach((rate, index) => {
      const base = baseByRate.get(rate) || 0;
      if (index < sortedRates.length - 1) {
        const discounted = roundCurrency(base * discountFactor);
        discountedBaseByRate.set(rate, discounted);
        otherGroupsTotal = roundCurrency(otherGroupsTotal + discounted);
      } else {
        discountedBaseByRate.set(rate, roundCurrency(subtotal - otherGroupsTotal));
      }
    });
  } else {
    for (const [rate, base] of baseByRate.entries()) {
      discountedBaseByRate.set(rate, base);
    }
  }

  let totalTax = 0;
  for (const [rate, base] of discountedBaseByRate.entries()) {
    totalTax = roundCurrency(totalTax + roundCurrency(base * (rate / 100)));
  }

  const irpf = roundCurrency(subtotal * (docIrpfRate / 100));
  const surcharge = roundCurrency(subtotal * (docSurchargeRate / 100));
  return roundCurrency(subtotal + totalTax + surcharge - irpf);
};

const resolveDocumentAmount = (doc, defaultCurrency = 'EUR') => {
  const docCurrency =
    doc && typeof doc.currency === 'string' && doc.currency.trim().length > 0
      ? doc.currency.trim().toUpperCase()
      : defaultCurrency;

  if (doc && typeof doc.total === 'number' && Number.isFinite(doc.total)) {
    return {
      amount: roundCurrency(doc.total),
      currency: docCurrency,
      provenance: 'stored_field',
      fieldOrFormula: 'doc.total'
    };
  }
  if (doc && typeof doc.amount === 'number' && Number.isFinite(doc.amount)) {
    return {
      amount: roundCurrency(doc.amount),
      currency: docCurrency,
      provenance: 'stored_field',
      fieldOrFormula: 'doc.amount'
    };
  }
  const derived = computeCanonicalDocumentTotal(doc);
  if (derived !== null) {
    return {
      amount: derived,
      currency: docCurrency,
      provenance: 'derived_from_items',
      fieldOrFormula: 'canonical:round2(subtotal_after_line_and_doc_discount + tax + surcharge - irpf)'
    };
  }
  return {
    amount: null,
    currency: docCurrency,
    provenance: 'unavailable',
    fieldOrFormula: 'missing:total|amount|supported_canonical_items',
    unavailableCount: 1
  };
};

const sumProvenancedAmounts = (amounts, defaultCurrency = 'EUR') => {
  if (!Array.isArray(amounts) || amounts.length === 0) {
    return {
      amount: 0,
      currency: defaultCurrency,
      provenance: 'stored_field',
      fieldOrFormula: 'sum(0 items)',
      totalsByCurrency: {},
      unavailableCount: 0
    };
  }

  const totalsByCurrency = {};
  let unavailableCount = 0;
  let anyDerived = false;

  for (const item of amounts) {
    if (!item || item.amount === null || item.provenance === 'unavailable' || typeof item.amount !== 'number' || !Number.isFinite(item.amount)) {
      unavailableCount += item && typeof item.unavailableCount === 'number' ? item.unavailableCount : 1;
      continue;
    }
    const curr = item.currency || defaultCurrency;
    const bucket = totalsByCurrency[curr] || {
      amount: 0,
      count: 0,
      provenance: 'stored_field'
    };
    bucket.amount = roundCurrency(bucket.amount + item.amount);
    bucket.count += 1;
    if (item.provenance === 'derived_from_items') {
      bucket.provenance = 'derived_from_items';
      anyDerived = true;
    }
    totalsByCurrency[curr] = bucket;
  }

  const currencies = Object.keys(totalsByCurrency);

  if (unavailableCount > 0) {
    const bucketCurrency =
      currencies.length === 1
        ? currencies[0]
        : currencies.length > 1
          ? 'MIXED'
          : defaultCurrency;
    return {
      amount: null,
      currency: bucketCurrency,
      provenance: 'unavailable',
      fieldOrFormula: `unavailable(${unavailableCount} of ${amounts.length} documents missing canonical amount)`,
      totalsByCurrency,
      unavailableCount
    };
  }

  if (currencies.length > 1) {
    return {
      amount: null,
      currency: 'MIXED',
      provenance: 'mixed_currency_unconverted',
      fieldOrFormula: `mixed_currencies(${currencies.join(',')}):no_fx_conversion_applied`,
      totalsByCurrency,
      unavailableCount: 0
    };
  }

  const singleCurr = currencies[0];
  const singleBucket = totalsByCurrency[singleCurr];
  return {
    amount: singleBucket.amount,
    currency: singleCurr,
    provenance: anyDerived ? 'derived_from_items' : 'stored_field',
    fieldOrFormula: `sum(${amounts.length} items in ${singleCurr})`,
    totalsByCurrency,
    unavailableCount: 0
  };
};

const formatProvenancedAmount = (pa) => {
  if (pa.provenance === 'mixed_currency_unconverted' && pa.totalsByCurrency) {
    const parts = Object.entries(pa.totalsByCurrency).map(
      ([curr, b]) => `${b.amount.toFixed(2)} ${curr} (${b.count} doc(s), ${b.provenance})`
    );
    return `Multi-divisa sin convertir [${parts.join('; ')}]`;
  }
  if (pa.amount === null || pa.provenance === 'unavailable') {
    const partialParts = pa.totalsByCurrency
      ? Object.entries(pa.totalsByCurrency).map(
          ([curr, b]) => `${b.amount.toFixed(2)} ${curr} (${b.count} doc(s))`
        )
      : [];
    const partialSuffix =
      partialParts.length > 0
        ? ` — subtotal parcial verificado: ${partialParts.join('; ')}`
        : '';
    return `No disponible (${pa.unavailableCount || 1} doc(s) sin importe determinable [${pa.fieldOrFormula}]${partialSuffix})`;
  }
  return `${pa.amount.toFixed(2)} ${pa.currency} (${pa.provenance})`;
};

const asOfDate = $('Set Brief Window').item.json.asOfDate;
const periodMonth = asOfDate.slice(0, 7);
const todayMs = new Date(asOfDate + 'T00:00:00Z').getTime();
const dayMs = 86400000;

const invoices = $('List Recent Invoices').all().map(i => i.json);
const quotes = $('List Recent Quotes').all().map(q => q.json);
const expenses = $('List Recent Expenses').all().map(e => e.json);

const draftInvoices = invoices
  .filter(i => i.status === 'draft')
  .map(i => ({ ...i, resolvedAmount: resolveDocumentAmount(i, 'EUR') }));
const issuedOpenInvoices = invoices
  .filter(i => ['sent', 'overdue', 'partial', 'partially_paid', 'unpaid', 'issued'].includes(i.status))
  .map(i => ({ ...i, resolvedAmount: resolveDocumentAmount(i, 'EUR') }));

const overdueInvoices = [];
const dueSoonInvoices = [];
for (const inv of issuedOpenInvoices) {
  const dueStr = (inv.dueDate || '').slice(0, 10);
  const dueMs = dueStr ? new Date(dueStr + 'T00:00:00Z').getTime() : NaN;
  const diffDays = Number.isFinite(dueMs) ? Math.round((dueMs - todayMs) / dayMs) : null;
  if (inv.status === 'overdue' || (diffDays !== null && diffDays < 0)) {
    overdueInvoices.push({ ...inv, daysOverdue: diffDays !== null ? Math.abs(diffDays) : null });
  } else if (diffDays !== null && diffDays >= 0 && diffDays <= 7) {
    dueSoonInvoices.push({ ...inv, daysUntilDue: diffDays });
  }
}

const expiringQuotes = quotes
  .filter(q => {
    if (q.status !== 'sent') return false;
    const validStr = (q.validUntil || '').slice(0, 10);
    if (!validStr) return true;
    const diffDays = Math.round((new Date(validStr + 'T00:00:00Z').getTime() - todayMs) / dayMs);
    return diffDays <= 7;
  })
  .map(q => ({ ...q, resolvedAmount: resolveDocumentAmount(q, 'EUR') }));

const expensesToReview = expenses
  .map(e => ({ ...e, resolvedAmount: resolveDocumentAmount(e, 'EUR') }))
  .filter(e => !e.vendor || !e.category || e.taxDeductible === false || e.resolvedAmount.provenance === 'unavailable');

const overdueTotal = sumProvenancedAmounts(overdueInvoices.map(i => i.resolvedAmount), 'EUR');
const dueSoonTotal = sumProvenancedAmounts(dueSoonInvoices.map(i => i.resolvedAmount), 'EUR');
const openIssuedNominalTotal = sumProvenancedAmounts(issuedOpenInvoices.map(i => i.resolvedAmount), 'EUR');
const draftExcludedTotal = sumProvenancedAmounts(draftInvoices.map(i => i.resolvedAmount), 'EUR');
const expiringQuotesTotal = sumProvenancedAmounts(expiringQuotes.map(q => q.resolvedAmount), 'EUR');
const totalSampledExpenses = sumProvenancedAmounts(expenses.map(e => resolveDocumentAmount(e, 'EUR')), 'EUR');

const isInPeriodMonth = (dateStr) => typeof dateStr === 'string' && dateStr.slice(0, 7) === periodMonth;
const issuedInvoicesInMonth = invoices.filter(i => !['draft', 'cancelled', 'void', 'voided'].includes(i.status) && isInPeriodMonth(i.issueDate || i.date));
const draftInvoicesInMonth = draftInvoices.filter(i => isInPeriodMonth(i.issueDate || i.date));
const quotesInMonth = quotes.filter(q => isInPeriodMonth(q.issueDate || q.date));
const expensesInMonth = expenses.filter(e => isInPeriodMonth(e.date || e.expenseDate));

const currentMonthActivity = {
  referenceMonth: periodMonth,
  scopeNote: `Subconjunto de registros dentro de la muestra cuya fecha pertenece a ${periodMonth}, separado de la muestra operativa abierta al ${asOfDate}.`,
  issuedInvoicesInMonthCount: issuedInvoicesInMonth.length,
  issuedInvoicesInMonthTotal: sumProvenancedAmounts(issuedInvoicesInMonth.map(i => resolveDocumentAmount(i, 'EUR')), 'EUR'),
  draftInvoicesInMonthCount: draftInvoicesInMonth.length,
  draftInvoicesInMonthTotal: sumProvenancedAmounts(draftInvoicesInMonth.map(i => i.resolvedAmount), 'EUR'),
  quotesCreatedInMonthCount: quotesInMonth.length,
  quotesCreatedInMonthTotal: sumProvenancedAmounts(quotesInMonth.map(q => resolveDocumentAmount(q, 'EUR')), 'EUR'),
  expensesInMonthCount: expensesInMonth.length,
  expensesInMonthTotal: sumProvenancedAmounts(expensesInMonth.map(e => resolveDocumentAmount(e, 'EUR')), 'EUR')
};

const unpaidNominalLabel = 'Importe nominal de facturas no marcadas como pagadas (saldo pendiente real no determinable sin cobros parciales)';

const lines = [
  `*Frihet Daily Operational Brief (${asOfDate})*`,
  `_¿Qué debería revisar hoy en mi negocio y por qué?_`,
  '',
  '*1. Cobertura y Alcance Temporal*',
  `• Alcance temporal: unfiltered_operational_sample_as_of_date (muestra operativa abierta al ${asOfDate} + desglose del mes ${periodMonth})`,
  '',
  '*2. Cobros y Vencimientos (Issued Receivables — excludes drafts)*',
  `• ${unpaidNominalLabel} (${issuedOpenInvoices.length}): *${formatProvenancedAmount(openIssuedNominalTotal)}*`,
  `• Facturas vencidas (P1) (${overdueInvoices.length}): *${formatProvenancedAmount(overdueTotal)}*`,
  `• Próximos vencimientos ≤7 días (P2) (${dueSoonInvoices.length}): *${formatProvenancedAmount(dueSoonTotal)}*`,
  `• Borradores no emitidos excluidos de cuentas por cobrar (${draftInvoices.length}): ${formatProvenancedAmount(draftExcludedTotal)}`,
  '',
  '*3. Presupuestos por Seguimiento (P2)*',
  `• Presupuestos enviados próximos a expirar (${expiringQuotes.length}): ${formatProvenancedAmount(expiringQuotesTotal)}`,
  '',
  '*4. Gastos por Revisar (P3)*',
  `• Gastos sin proveedor/categoría o marcados no deducibles (taxDeductible=false estado válido): ${expensesToReview.length} (total muestra: ${formatProvenancedAmount(totalSampledExpenses)})`,
  '',
  `*5. Actividad del Mes en Curso (${periodMonth}) vs Muestra Operativa*`,
  `• Facturas emitidas en ${periodMonth} (${currentMonthActivity.issuedInvoicesInMonthCount}): ${formatProvenancedAmount(currentMonthActivity.issuedInvoicesInMonthTotal)}`,
  `• Gastos fechados en ${periodMonth} (${currentMonthActivity.expensesInMonthCount}): ${formatProvenancedAmount(currentMonthActivity.expensesInMonthTotal)}`,
  '',
  '*6. Safety & Approval Gate*',
  '• All follow-up actions (sending reminders, issuing drafts, logging CRM calls) require human approval (`humanApprovalRequired: true`, `autoExecuted: false`).',
  '• Known unknown: Bank account balances and partial payments are not inferred (`realOutstandingBalanceDeterminable: false`).'
];

return [{
  json: {
    asOfDate,
    question: '¿Qué debería revisar hoy en mi negocio y por qué?',
    coverage: {
      temporalScope: 'unfiltered_operational_sample_as_of_date'
    },
    collectionsAndDueDates: {
      overdueCount: overdueInvoices.length,
      overdueTotal,
      upcomingDueWithin7DaysCount: dueSoonInvoices.length,
      upcomingDueWithin7DaysTotal: dueSoonTotal,
      openIssuedCount: issuedOpenInvoices.length,
      openIssuedNominalTotal,
      realOutstandingBalanceDeterminable: false,
      unpaidNominalSemantics: 'nominal_unpaid_invoice_totals_without_partial_payments',
      unpaidNominalLabel,
      draftExcludedCount: draftInvoices.length,
      draftExcludedTotal
    },
    currentMonthActivity,
    overdueCount: overdueInvoices.length,
    overdueTotal,
    dueSoonCount: dueSoonInvoices.length,
    draftCount: draftInvoices.length,
    draftTotal: draftExcludedTotal,
    expiringQuotesCount: expiringQuotes.length,
    expensesToReviewCount: expensesToReview.length,
    humanApprovalRequired: true,
    autoExecuted: false,
    slackMessage: lines.join('\n')
  }
}];
